'use strict';
const TODAY='2026-11-03', MRN='26GR00000000000001';
const q=new URLSearchParams(location.search);
const choices={layout:['compare','a','b','c','reference'],view:['details','create'],scenario:['full','partial','draft','documentary','physical','no-payment','paid','complete','cancelled','readonly'],state:['default','loading','empty','error']};
const pick=(key,fallback)=>choices[key].includes(q.get(key))?q.get(key):fallback;
let ui={lang:q.get('lang')==='el'?'el':'en',layout:pick('layout','compare'),view:pick('view','details'),scenario:pick('scenario','full'),state:pick('state','default'),tab:'goods',notes:q.get('notes')==='1',edit:false};
const tx=(en,el)=>ui.lang==='el'?el:en;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses={draft:['Awaiting submission','Αναμονή υποβολής'],result:['Awaiting customs result','Αναμονή αποτελέσματος τελωνείου'],documentary:['Awaiting documentary inspection','Αναμονή ελέγχου εγγράφων'],physical:['Awaiting physical inspection','Αναμονή φυσικού ελέγχου'],payment:['Awaiting payment','Αναμονή πληρωμής'],permit:['Awaiting Άδεια Τελωνισθέντων Εμπορευμάτων','Αναμονή Άδειας Τελωνισθέντων Εμπορευμάτων'],complete:['Completed','Ολοκληρώθηκε']};
const stageText=s=>tx(...statuses[s]);
const companies=['Demo Shipper Alpha','Demo Shipper Beta','Demo Logistics Gamma'];
const goods=[{id:'DEMO-HU-001',order:'DEMO-201',desc:['Pump assembly','Συγκρότημα αντλίας'],dim:'80 × 60 × 55 cm',kg:45},{id:'DEMO-HU-002',order:'DEMO-201',desc:['Valve set','Σετ βαλβίδων'],dim:'65 × 45 × 40 cm',kg:70},{id:'DEMO-HU-003',order:'DEMO-202',desc:['Electrical parts','Ηλεκτρολογικά εξαρτήματα'],dim:'60 × 40 × 35 cm',kg:32}];
const eventNames={submission:['Submission confirmed','Επιβεβαίωση υποβολής'],documentary:['Documentary inspection required','Απαιτείται έλεγχος εγγράφων'],physical:['Physical inspection required','Απαιτείται φυσικός έλεγχος'],inspection:['Inspection completed; result pending','Ο έλεγχος ολοκληρώθηκε · αναμονή αποτελέσματος'],positive:['Positive result confirmed','Επιβεβαίωση θετικού αποτελέσματος'],payment:['Payment confirmed','Επιβεβαίωση πληρωμής'],receipt:['Άδεια receipt confirmed','Επιβεβαίωση παραλαβής Άδειας'],created:['Import created','Δημιουργία εισαγωγής'],edited:['Import fields updated','Ενημέρωση στοιχείων εισαγωγής'],cancel:['Record cancelled','Ακύρωση εγγραφής']};
let record,form,editDraft,modalKind='',lastFocus=null,toastTimer;
const blocked=()=>ui.scenario==='partial'?['DEMO-HU-001']:[];
const eligible=()=>goods.filter(g=>!blocked().includes(g.id));
const afterPositive=r=>['payment','permit','complete'].includes(r.stage);
const canEdit=()=>!record.cancelled&&ui.scenario!=='readonly';
const ev=(kind,date=TODAY,extra={})=>({kind,date,...extra});
function resetFixture(){
 record={id:'IMP-DEMO-021',shipment:'SHP-DEMO-104',selected:eligible().map(g=>g.id),shipper:companies[0],stage:'result',payment:null,mrn:MRN,mrnDate:TODAY,cancelled:false,files:[],events:[ev('created'),ev('submission')]};
 if(['draft','partial','cancelled'].includes(ui.scenario)){record.stage='draft';record.mrn='';record.mrnDate='';record.events=[ev('created')];}
 if(['documentary','physical'].includes(ui.scenario)){record.stage=ui.scenario;record.events.push(ev(ui.scenario));}
 if(['no-payment','paid','complete'].includes(ui.scenario)){record.payment=ui.scenario!=='no-payment';record.stage=ui.scenario==='complete'?'complete':'permit';record.events.push(ev('positive',TODAY,{payment:record.payment}));if(record.payment)record.events.push(ev('payment'));if(record.stage==='complete')record.events.push(ev('receipt'));}
 if(ui.scenario==='cancelled'){record.cancelled=true;record.reason=tx('Wrong sample record','Λανθασμένη δοκιμαστική εγγραφή');record.events.push(ev('cancel'));}
 form={shipment:'',shipper:'',selected:[],advanced:false,stage:'result',payment:'yes',mrn:'',mrnDate:'',submissionDate:'',inspectionDate:'',positiveDate:'',paymentDate:'',receiptDate:''};ui.tab='goods';ui.edit=false;editDraft=null;
}
resetFixture();
const btn=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const fresh=()=>`<span class="new">${tx('New component','Νέο στοιχείο')}</span>`;
const mark=n=>`<button type="button" class="marker" data-action="note" data-n="${n}" aria-label="${tx('Business rule','Επιχειρησιακός κανόνας')} ${n}">${n}</button>`;
const badge=()=>`<span class="badge ${record.cancelled?'danger':record.stage==='complete'?'success':record.stage==='draft'?'neutral':['documentary','physical','payment'].includes(record.stage)?'warning':''}">${esc(record.cancelled?tx('Cancelled','Ακυρώθηκε'):stageText(record.stage))}</span>`;
const field=(name,label,value='',type='text',hint='',required=false)=>`<label class="field"><span>${label}${required?' *':''}</span><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='date'?`max="${TODAY}"`:''} ${required?'required':''}>${hint?`<small>${hint}</small>`:''}</label>`;
const companySelect=(value,name='shipper')=>`<label class="field"><span>${tx('Shipper','Αποστολέας')} ${mark(2)}</span><select id="${name}" name="${name}"><option value="">${tx('Select an existing company','Επιλέξτε υπάρχουσα εταιρεία')}</option>${companies.map(c=>`<option ${c===value?'selected':''}>${c}</option>`).join('')}</select><small>${tx('Required when submission is confirmed.','Απαιτείται κατά την επιβεβαίωση υποβολής.')}</small></label>`;
function syncUrl(){if(location.protocol==='file:')return;const p=new URLSearchParams({layout:ui.layout,view:ui.view,scenario:ui.scenario,state:ui.state,lang:ui.lang});if(ui.notes)p.set('notes','1');history.replaceState(null,'','?'+p);}
function announce(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),5500);}
function reviewer(){
 const scenarios=[['full','Full clearance','Πλήρης εκτελωνισμός'],['partial','Later partial declaration','Επόμενη μερική διασάφηση'],['draft','Before submission','Πριν από την υποβολή'],['documentary','Documentary inspection','Έλεγχος εγγράφων'],['physical','Physical inspection','Φυσικός έλεγχος'],['no-payment','No payment required','Δεν απαιτείται πληρωμή'],['paid','Paid, awaiting Άδεια','Πληρωμή · αναμονή Άδειας'],['complete','Completed','Ολοκληρωμένο'],['cancelled','Cancelled record','Ακυρωμένη εγγραφή'],['readonly','Read-only review','Προβολή χωρίς επεξεργασία']];
 return `<div class="review-bar"><div class="review-top"><div class="row"><span class="review-id">FRO-360 / ${tx('LOCAL REVIEW','ΤΟΠΙΚΗ ΠΡΟΕΠΙΣΚΟΠΗΣΗ')}</span>${fresh()}</div><div class="review-controls"><label>${tx('Layout','Διάταξη')}<select id="layout" data-control="layout">${[['compare','Compare directions','Σύγκριση προτάσεων'],['a','A · Overview first','A · Επισκόπηση'],['b','B · Action first','B · Επόμενη ενέργεια'],['c','C · Context first','C · Πληροφορίες μαζί'],['reference','Shipment reference','Αναφορά Shipment']].map(([v,en,el])=>`<option value="${v}" ${ui.layout===v?'selected':''}>${tx(en,el)}</option>`).join('')}</select></label><label>${tx('Scenario','Σενάριο')}<select id="scenario" data-control="scenario">${scenarios.map(([v,en,el])=>`<option value="${v}" ${ui.scenario===v?'selected':''}>${tx(en,el)}</option>`).join('')}</select></label><label>${tx('Page state','Κατάσταση σελίδας')}<select id="state" data-control="state">${[['default','Default','Κανονική'],['loading','Loading','Φόρτωση'],['empty','Empty','Χωρίς δεδομένα'],['error','Error','Σφάλμα']].map(([v,en,el])=>`<option value="${v}" ${ui.state===v?'selected':''}>${tx(en,el)}</option>`).join('')}</select></label><div class="lang"><button class="${ui.lang==='en'?'active':''}" data-action="lang" data-lang="en" aria-label="English" aria-pressed="${ui.lang==='en'}">EN</button><button class="${ui.lang==='el'?'active':''}" data-action="lang" data-lang="el" aria-label="Ελληνικά" aria-pressed="${ui.lang==='el'}">EL</button></div>${btn(tx('Rule notes','Κανόνες'),'notes','sm',`aria-expanded="${ui.notes}"`)}${btn(tx('Reset','Επαναφορά'),'reset','sm')}</div></div></div><div class="preview-notice">${tx('Concept preview · sample data · changes are not saved · no production connection','Προεπισκόπηση ιδέας · δοκιμαστικά δεδομένα · οι αλλαγές δεν αποθηκεύονται · χωρίς σύνδεση με την παραγωγή')}</div>`;
}
function shell(){return `<header class="chrome"><div class="chrome-inner"><div class="brand">FRONT <span>LINE</span></div><nav class="nav" aria-label="${tx('Preview navigation','Πλοήγηση προεπισκόπησης')}"><button data-action="reference">${tx('Shipments','Αποστολές')}</button><button data-action="nav-info">${tx('Orders','Παραγγελίες')}</button><button class="active" data-action="details">${tx('Imports','Εισαγωγές')}</button><button data-action="nav-info">${tx('Exports','Εξαγωγές')}</button><button data-action="nav-info">${tx('Companies','Εταιρείες')}</button></nav><div class="user"><span class="avatar">DO</span>${tx('Demo operator','Δοκιμαστικός χρήστης')}</div></div></header>`;}
const directions={a:['Overview first','Επισκόπηση πρώτα','Import facts and covered goods lead. Customs actions and Shipment context stay alongside.','Πρώτα τα στοιχεία και τα καλυπτόμενα κόλι. Οι τελωνειακές ενέργειες και η αποστολή παραμένουν δίπλα.','Familiar record layout; related detail needs more scrolling.','Οικεία διάταξη εγγραφής · οι πρόσθετες πληροφορίες απαιτούν κύλιση.'],b:['Action first','Επόμενη ενέργεια πρώτα','Put the next customs action above the record, then review details and goods below.','Η επόμενη τελωνειακή ενέργεια πάνω από την εγγραφή, με στοιχεία και κόλι από κάτω.','Faster daily processing; transport context is less prominent.','Γρήγορη καθημερινή εργασία · λιγότερη έμφαση στα μεταφορικά στοιχεία.'],c:['Context first','Πληροφορίες μαζί','Give Shipment information and packing more room, next to the customs procedure.','Περισσότερος χώρος για αποστολή και συσκευασία, δίπλα στην τελωνειακή διαδικασία.','More information in one place; a denser working screen.','Περισσότερες πληροφορίες μαζί · πυκνότερη οθόνη εργασίας.']};
function mini(k){return `<div class="mini mini-${k}" aria-hidden="true"><div class="mini-chrome"></div><div class="mini-title">IMP-DEMO-021 <span>● ${tx('Awaiting result','Αναμονή αποτελέσματος')}</span></div>${k==='b'?`<div class="mini-box mini-hero"><b>${tx('What happens next?','Επόμενη ενέργεια')}</b><div class="mini-line accent"></div></div>`:''}<div class="mini-grid"><div class="stack" style="gap:7px"><div class="mini-box"><b>${k==='c'?tx('Shipment · read-only','Αποστολή · μόνο ανάγνωση'):tx('Import details','Στοιχεία εισαγωγής')}</b><div class="mini-line"></div><div class="mini-line"></div></div><div class="mini-box"><b>${tx('Covered goods','Καλυπτόμενα κόλι')}</b><div class="mini-line"></div><div class="mini-line"></div></div></div><div class="mini-box"><b>${k==='c'?tx('Customs procedure','Τελωνειακή διαδικασία'):tx('Next action','Επόμενη ενέργεια')}</b><div class="mini-line accent"></div><div class="mini-button">${tx('Confirm result','Επιβεβαίωση')}</div></div></div></div>`;}
function compare(){return `<div class="compare-intro"><div class="overline">${tx('Import Customs Declaration · Concept round 1','Διασάφηση εισαγωγής · 1ος γύρος ιδεών')}</div><h1>${tx('Three ways to bring the work together','Τρεις τρόποι να οργανώσουμε την εργασία')}</h1><p class="subtitle">${tx('Same sample record. Same customs rules. Compare what should be visible first, then try a direction. These are proposals for discussion.','Ίδια δοκιμαστική εγγραφή και ίδιοι κανόνες. Συγκρίνετε τι πρέπει να φαίνεται πρώτο και δοκιμάστε μια πρόταση. Οι διατάξεις είναι προτάσεις προς συζήτηση.')}</p></div><div class="gallery">${Object.entries(directions).map(([k,d])=>`<article class="card direction-card">${mini(k)}<div class="card-body"><div class="row"><span class="direction-letter">${k.toUpperCase()}</span><h2>${tx(d[0],d[1])}</h2></div><p>${tx(d[2],d[3])}</p><p class="tradeoff">${tx(d[4],d[5])}</p><div class="row">${fresh()}<span class="small muted">${tx('Import workbench + action/context panels','Χώρος εισαγωγής + ενέργειες/πληροφορίες')}</span></div>${btn(tx('Explore '+k.toUpperCase(),'Δοκιμή '+k.toUpperCase()),'direction','primary',`data-layout="${k}"`)}</div></article>`).join('')}</div><section class="card spaced"><div class="card-body ref-strip"><div class="mini"><div class="mini-chrome"></div><div class="mini-title">SHP-DEMO-104</div><div class="mini-grid"><div class="mini-box"><b>${tx('Transport & timing','Μεταφορά & χρόνοι')}</b><div class="mini-line"></div></div><div class="mini-box"><b>${tx('Purchase orders','Παραγγελίες')}</b><div class="mini-line"></div></div></div></div><div class="stack"><div><div class="overline">${tx('Existing screen reference','Αναφορά υπάρχουσας οθόνης')}</div><h2>${tx('The Shipment stays a separate record','Η αποστολή παραμένει ξεχωριστή εγγραφή')}</h2><p class="subtitle">${tx('A fixture reconstruction of current Shipment sections helps compare the new Import workspace with familiar portal patterns.','Αναπαράσταση των σημερινών ενοτήτων αποστολής με δοκιμαστικά δεδομένα, για σύγκριση με τα οικεία μοτίβα της πύλης.')}</p></div><div class="row">${btn(tx('View Shipment reference','Προβολή αναφοράς αποστολής'),'reference')}${btn(tx('Try creation flow','Δοκιμή δημιουργίας'),'create')}</div></div></div></section><div class="notice warning spaced">${mark(6)} ${tx('Open question: can customs clear only part of a colli’s contents? Whole-colli selection is provisional, not a confirmed limitation.','Ανοιχτό ερώτημα: μπορεί να εκτελωνιστεί μέρος του περιεχομένου ενός κόλι; Η επιλογή ολόκληρων κόλι είναι προσωρινή παραδοχή.')}</div>`;}
function factsCard(){const r=record;return `<section class="card"><div class="card-head"><h2>${tx('Import details','Στοιχεία εισαγωγής')} ${mark(2)}</h2>${canEdit()&&(!afterPositive(r))?btn(tx('Edit','Επεξεργασία'),'edit','sm'):''}</div><div class="card-body"><dl class="facts"><div><dt>${tx('Import ID','Κωδικός εισαγωγής')}</dt><dd class="mono">${r.id}</dd></div><div><dt>${tx('Shipment','Αποστολή')} · ${tx('fixed','σταθερή')}</dt><dd><button class="link-button mono" data-action="reference">${r.shipment}</button></dd></div><div><dt>${tx('Shipper','Αποστολέας')}${r.stage!=='draft'?' · '+tx('locked','κλειδωμένος'):''}</dt><dd>${esc(r.shipper)||'—'}</dd></div><div><dt>${tx('Payment requirement','Απαίτηση πληρωμής')}</dt><dd>${r.payment===null?'—':r.payment?tx('Payment required','Απαιτείται πληρωμή'):tx('No payment required','Δεν απαιτείται πληρωμή')}</dd></div><div><dt>MRN ${afterPositive(r)?'· '+tx('locked','κλειδωμένο'):''}</dt><dd class="mono">${r.mrn||'—'}</dd></div><div><dt>${tx('MRN date','Ημερομηνία MRN')}</dt><dd>${r.mrnDate||'—'}</dd></div></dl></div><div class="card-foot">${tx('Import-owned facts. Related Shipment data is read-only.','Στοιχεία της εισαγωγής. Τα σχετικά στοιχεία αποστολής είναι μόνο για ανάγνωση.')}</div></section>`;}
function actionCard(hero=false){
 let r=record,actions='',desc='';const c=(en,el,action,cls='')=>btn(tx(en,el),action,cls);
 if(r.cancelled)desc=tx('This cancelled sample retains its history. No further actions are available.','Η ακυρωμένη εγγραφή διατηρεί το ιστορικό της. Δεν υπάρχουν άλλες ενέργειες.');
 else if(ui.scenario==='readonly')desc=tx('Read-only review. Confirmation and edit actions are unavailable.','Προβολή χωρίς επεξεργασία. Οι επιβεβαιώσεις και οι αλλαγές δεν είναι διαθέσιμες.');
 else switch(r.stage){
 case'draft':desc=tx('Review the selected goods and Shipper before confirming that the declaration was submitted.','Ελέγξτε τα επιλεγμένα κόλι και τον αποστολέα πριν επιβεβαιώσετε την υποβολή.');actions=c('Confirm submission','Επιβεβαίωση υποβολής','submit','primary');break;
 case'result':desc=tx('Record the result received from customs. An inspection referral is not a rejection.','Καταχωρίστε το αποτέλεσμα του τελωνείου. Η παραπομπή σε έλεγχο δεν είναι απόρριψη.');actions=c('Confirm positive result','Επιβεβαίωση θετικού αποτελέσματος','positive','primary')+c('Documentary inspection','Έλεγχος εγγράφων','documentary')+c('Physical inspection','Φυσικός έλεγχος','physical');break;
 case'documentary':case'physical':desc=tx('If the inspection finishes without a result, return to awaiting result. A positive result must be confirmed explicitly.','Αν ολοκληρωθεί ο έλεγχος χωρίς αποτέλεσμα, επιστρέψτε στην αναμονή. Το θετικό αποτέλεσμα επιβεβαιώνεται ρητά.');actions=c('Confirm positive result','Επιβεβαίωση θετικού αποτελέσματος','positive','primary')+c('Inspection done · result pending','Ο έλεγχος τελείωσε · αναμονή αποτελέσματος','inspection');break;
 case'payment':desc=tx('Confirm payment when it has actually occurred. Payment does not complete the customs procedure.','Επιβεβαιώστε την πληρωμή όταν έχει πραγματοποιηθεί. Η πληρωμή δεν ολοκληρώνει την τελωνειακή διαδικασία.');actions=c('Confirm payment','Επιβεβαίωση πληρωμής','payment','primary');break;
 case'permit':desc=tx('Complete the Import only when the Άδεια Τελωνισθέντων Εμπορευμάτων has been received. Uploading a file is optional.','Ολοκληρώστε την εισαγωγή μόνο όταν παραληφθεί η Άδεια Τελωνισθέντων Εμπορευμάτων. Η επισύναψη είναι προαιρετική.');actions=c('Confirm Άδεια receipt','Επιβεβαίωση παραλαβής Άδειας','receipt','primary');break;
 case'complete':desc=tx('Άδεια receipt is confirmed. The customs procedure is complete; the record and history remain readable.','Η παραλαβή της Άδειας έχει επιβεβαιωθεί. Η τελωνειακή διαδικασία ολοκληρώθηκε και το ιστορικό παραμένει διαθέσιμο.');break;
 }
 return `<section class="card action-card ${hero?'action-hero':''}"><div class="card-head"><h2>${tx('Customs procedure','Τελωνειακή διαδικασία')} ${mark(3)}</h2>${fresh()}</div><div class="card-body"><div class="stack" style="gap:10px">${badge()}<div class="action-title">${r.stage==='complete'?tx('Completion evidence received','Παραλήφθηκε το αποδεικτικό ολοκλήρωσης'):tx('What happens next?','Ποιο είναι το επόμενο βήμα;')}</div><p class="action-text">${desc}</p></div>${actions?`<div class="action-buttons">${actions}</div>`:''}</div></section>`;
}
function goodsTable(selected,editable=false){
 return `<div class="table-wrap"><table><thead><tr>${editable?'<th class="checkcell"></th>':''}<th>${tx('Colli / description','Κόλι / περιγραφή')}</th><th>${tx('Dimensions','Διαστάσεις')}</th><th>${tx('Gross','Μικτό')}</th></tr></thead><tbody>${['DEMO-201','DEMO-202'].map(order=>{let rows=goods.filter(g=>g.order===order&&(editable||selected.includes(g.id)));if(!rows.length)return'';let available=rows.filter(g=>!blocked().includes(g.id));return `<tr class="group-row"><td colspan="${editable?4:3}">${editable?`<label class="check-label"><input type="checkbox" data-group="${order}" ${available.length&&available.every(g=>selected.includes(g.id))?'checked':''} ${!available.length?'disabled':''}>${tx('Order','Παραγγελία')} <span class="mono">${order}</span></label>`:`${tx('Order','Παραγγελία')} <span class="mono">${order}</span>`}</td></tr>${rows.map(g=>{const unavailable=editable&&blocked().includes(g.id);return `<tr class="${unavailable?'disabled-row':''}">${editable?`<td class="checkcell"><input type="checkbox" data-colli="${g.id}" aria-label="${g.id}" ${selected.includes(g.id)?'checked':''} ${unavailable?'disabled':''}></td>`:''}<td><div class="mono">${g.id}</div><span class="small muted">${tx(...g.desc)}</span>${unavailable?`<div class="small">${tx('Covered by IMP-DEMO-007','Καλύπτεται από IMP-DEMO-007')}</div>`:''}</td><td class="nowrap mono small">${g.dim}</td><td class="nowrap mono small">${g.kg} kg</td></tr>`;}).join('')}`;}).join('')}</tbody></table></div>`;
}
function historyHtml(){return `<ol class="history">${[...record.events].reverse().map(e=>`<li><strong>${tx(...eventNames[e.kind])}</strong><small>${e.date} · ${tx('Recorded by Demo operator','Καταχώριση από δοκιμαστικό χρήστη')}</small>${e.kind==='positive'?`<span class="small">${e.payment?tx('Payment required','Απαιτείται πληρωμή'):tx('No payment required','Δεν απαιτείται πληρωμή')}</span>`:''}</li>`).join('')}</ol>`;}
function filesHtml(){return `<div class="card-body"><p class="small muted">${tx('Optional sample files. Simulating an attachment never changes customs status.','Προαιρετικά δοκιμαστικά αρχεία. Η προσομοίωση επισύναψης δεν αλλάζει την τελωνειακή κατάσταση.')}</p>${record.files.length?record.files.map(f=>`<div class="file-row"><span class="file-icon">PDF</span><div class="name">${esc(f.name)}<small>${tx('Fixture only · no file was uploaded','Δοκιμαστικό · δεν μεταφορτώθηκε αρχείο')}</small></div>${!afterPositive(record)&&canEdit()?btn(tx('Remove','Αφαίρεση'),'file-remove','sm',`data-id="${f.id}"`):'<span class="tag">'+tx('Retained','Διατηρείται')+'</span>'}</div>`).join(''):`<div class="empty" style="padding:24px"><p>${tx('No files attached','Δεν υπάρχουν συνημμένα')}</p></div>`}${canEdit()?btn(tx('Simulate an attachment','Προσομοίωση επισύναψης'),'file-add','spaced'):''}</div>`;}
function goodsCard(){let body=ui.tab==='history'?`<div class="card-body">${historyHtml()}</div>`:ui.tab==='files'?filesHtml():`${record.selected.length?goodsTable(record.selected):`<div class="empty"><p>${tx('No goods selected yet','Δεν έχουν επιλεγεί κόλι')}</p></div>`}<div class="card-foot">${mark(1)} ${record.selected.length} ${tx('covered collis · grouping by the linked Shipment’s Orders','καλυπτόμενα κόλι · ομαδοποίηση από τις παραγγελίες της συνδεδεμένης αποστολής')}. ${record.stage!=='draft'?tx('Coverage locked at submission.','Η κάλυψη κλείδωσε στην υποβολή.'):tx('Coverage can be edited before submission.','Η κάλυψη αλλάζει πριν από την υποβολή.')}</div>`;return `<section class="card"><div class="section-nav" aria-label="${tx('Record sections','Ενότητες εγγραφής')}">${[['goods','Covered goods','Καλυπτόμενα κόλι'],['history','History','Ιστορικό'],['files','Files','Αρχεία']].map(([id,en,el])=>`<button data-action="tab" data-tab="${id}" class="${ui.tab===id?'active':''}" aria-pressed="${ui.tab===id}">${tx(en,el)}<span class="count">${id==='goods'?record.selected.length:id==='history'?record.events.length:record.files.length}</span></button>`).join('')}</div>${body}</section>`;}
function shipmentContext(expanded=false,reference=false){return `<section class="card"><div class="card-head"><h2>${tx('Shipment context','Στοιχεία αποστολής')} ${mark(4)}</h2>${reference?'':fresh()}</div><div class="context-top"><div class="row between"><span class="mono">SHP-DEMO-104</span><span class="source-tag">${tx('Read-only · Shipment','Μόνο ανάγνωση · αποστολή')}</span></div><p class="small muted spaced" style="margin-top:8px">${tx('All values below describe the whole Shipment, not only this declaration’s selected goods.','Τα στοιχεία αφορούν ολόκληρη την αποστολή, όχι μόνο τα κόλι αυτής της διασάφησης.')}</p></div><div class="card-body"><dl class="facts"><div class="wide"><dt>${tx('Transport document','Μεταφορικό έγγραφο')}</dt><dd class="mono">AWB · DEMO-AWB-104</dd></div><div><dt>${tx('Client','Πελάτης')}</dt><dd>Demo Client Alpha<small>DEMO-201, DEMO-202</small></dd></div><div><dt>${tx('Vessel','Πλοίο')}</dt><dd>Demo Vessel Blue<small>${tx('From the participating Orders','Από τις συμμετέχουσες παραγγελίες')}</small></dd></div>${expanded?`<div><dt>${tx('Physical status','Φυσική κατάσταση')}</dt><dd>${tx('Arrived','Αφίχθηκε')}</dd></div><div><dt>${tx('Transport pieces','Μονάδες μεταφοράς')}</dt><dd>2</dd></div>`:''}</dl>${expanded?`<div class="spaced"><div class="overline">${tx('Transport packing · whole Shipment','Συσκευασία μεταφοράς · όλη η αποστολή')}</div><div class="piece"><div><strong>${tx('Pallet DEMO-P1','Παλέτα DEMO-P1')}</strong><small>DEMO-HU-001 + DEMO-HU-002</small></div><div class="mono small">120 × 80 × 95 cm<br>120 kg</div></div><div class="piece"><div><strong>${tx('Individual colli','Μεμονωμένο κόλι')}</strong><small>DEMO-HU-003</small></div><div class="mono small">60 × 40 × 35 cm<br>32 kg</div></div><div class="row between spaced"><span>${tx('Whole-Shipment gross','Μικτό βάρος όλης της αποστολής')}</span><strong class="mono">152 kg</strong></div><p class="small muted">${tx('Illustrative fixture total; each transport piece is counted once. Field and total requirements remain for employee review.','Ενδεικτικό σύνολο δοκιμαστικών δεδομένων· κάθε μονάδα μετρά μία φορά. Τα πεδία και τα σύνολα παραμένουν προς συζήτηση.')}</p></div>`:btn(tx('Explore the full Shipment context','Πλήρη στοιχεία αποστολής'),'context','sm spaced')}</div><div class="card-foot">${tx('Candidate related fields — tell us what helps your daily work.','Υποψήφια σχετικά πεδία — πείτε μας τι χρειάζεστε στην καθημερινή εργασία.')}</div></section>`;}
function details(){let d=directions[ui.layout]||directions.a;return `<div class="page-top"><div><div class="breadcrumbs">${tx('Imports / Details','Εισαγωγές / Στοιχεία')}</div><div class="titleline"><h1>${record.id}</h1>${badge()}</div><p class="subtitle">${tx('One declaration · linked to','Μία διασάφηση · συνδέεται με')} <span class="mono">${record.shipment}</span> · ${record.selected.length} ${tx('collis','κόλι')}</p></div><div class="row">${btn(tx('Compare layouts','Σύγκριση διατάξεων'),'compare')}${btn(tx('Try creation','Δοκιμή δημιουργίας'),'create')}</div></div><div class="direction-note"><span class="direction-letter">${ui.layout.toUpperCase()}</span><div><strong>${tx(d[0],d[1])}</strong> <span class="small muted">${tx(d[4],d[5])}</span><div class="small">${fresh()} ${tx('Import workbench, action card and referenced-context composition','Χώρος εισαγωγής, κάρτα ενεργειών και σύνθεση σχετικών πληροφοριών')}</div></div></div>${record.cancelled?`<div class="notice warning spaced">${tx('Record cancelled. History and former coverage remain; this does not withdraw a customs declaration.','Η εγγραφή ακυρώθηκε. Διατηρείται το ιστορικό και η προηγούμενη κάλυψη· δεν ανακαλείται τελωνειακή διασάφηση.')}</div>`:''}${ui.layout==='b'?`<div style="margin-bottom:16px">${actionCard(true)}</div>`:''}<div class="layout ${ui.layout==='c'?'c':''}"><div class="stack">${ui.layout==='c'?shipmentContext(true):factsCard()}${goodsCard()}</div><aside class="stack">${ui.layout==='c'?factsCard():''}${ui.layout!=='b'?actionCard():''}${ui.layout!=='c'?shipmentContext(false):''}<div class="notice">${mark(5)} ${tx('Customs completion does not move goods or change the Order’s customs regime.','Η τελωνειακή ολοκλήρωση δεν μετακινεί κόλι και δεν αλλάζει το καθεστώς της παραγγελίας.')}</div></aside></div>${record.stage==='draft'&&canEdit()?`<div class="footer-note row between"><span>${tx('Mistaken pre-submission record? Cancellation is manager-only.','Λανθασμένη εγγραφή πριν την υποβολή; Η ακύρωση επιτρέπεται μόνο σε διαχειριστή.')}</span>${btn(tx('Simulate manager cancellation','Προσομοίωση ακύρωσης διαχειριστή'),'cancel-record','sm danger')}</div>`:''}`;}
function advancedFields(){let s=form.stage;let submitted=s!=='draft',positive=['payment','permit','complete'].includes(s),paid=positive&&s!=='payment'&&form.payment==='yes';return `<div class="form-grid"><label class="field"><span>${tx('Stage to record','Κατάσταση προς καταχώριση')}</span><select name="stage" id="entry-stage">${Object.keys(statuses).filter(s=>s!=='draft').map(s=>`<option value="${s}" ${form.stage===s?'selected':''}>${stageText(s)}</option>`).join('')}</select></label>${positive?`<label class="field"><span>${tx('Payment requirement','Απαίτηση πληρωμής')}</span><select name="payment" id="entry-payment"><option value="yes" ${form.payment==='yes'?'selected':''}>${tx('Payment required','Απαιτείται πληρωμή')}</option>${s==='payment'?'':`<option value="no" ${form.payment==='no'?'selected':''}>${tx('No payment required','Δεν απαιτείται πληρωμή')}</option>`}</select></label>`:''}${submitted?field('mrn','MRN',form.mrn,'text','',true)+field('mrnDate',tx('MRN date','Ημερομηνία MRN'),form.mrnDate,'date','',true)+field('submissionDate',tx('Submission confirmation date','Ημερομηνία επιβεβαίωσης υποβολής'),form.submissionDate,'date','',true):''}${['documentary','physical'].includes(s)?field('inspectionDate',tx('Inspection referral date','Ημερομηνία παραπομπής σε έλεγχο'),form.inspectionDate,'date','',true):''}${positive?field('positiveDate',tx('Positive-result confirmation date','Ημερομηνία επιβεβαίωσης θετικού αποτελέσματος'),form.positiveDate,'date','',true):''}${paid?field('paymentDate',tx('Payment confirmation date','Ημερομηνία επιβεβαίωσης πληρωμής'),form.paymentDate,'date','',true):''}${s==='complete'?field('receiptDate',tx('Άδεια receipt date','Ημερομηνία παραλαβής Άδειας'),form.receiptDate,'date','',true):''}</div><div class="notice spaced">${tx('Record only facts that are known. This example path has no earlier inspections; do not invent missing milestones.','Καταχωρίστε μόνο γνωστά γεγονότα. Η ενδεικτική διαδρομή δεν έχει προηγούμενους ελέγχους· μην επινοείτε ορόσημα.')}</div>${btn(tx('Use sample MRN and dates','Συμπλήρωση δοκιμαστικών MRN και ημερομηνιών'),'fixture-dates','sm spaced')}`;}
function creation(){return `<div class="page-top"><div><div class="breadcrumbs">${tx('Imports / New Import','Εισαγωγές / Νέα εισαγωγή')}</div><h1>${tx('Create Import','Δημιουργία εισαγωγής')}</h1><p class="subtitle">${tx('Start with a Shipment. All eligible goods are selected for the normal full-clearance case.','Ξεκινήστε από την αποστολή. Όλα τα επιλέξιμα κόλι επιλέγονται για τον συνήθη πλήρη εκτελωνισμό.')}</p></div>${btn(tx('Back to sample details','Επιστροφή στα δοκιμαστικά στοιχεία'),'details')}</div><div class="direction-note">${fresh()}<span>${tx('Shared creation concept · same behavior in all three directions','Κοινή πρόταση δημιουργίας · ίδια συμπεριφορά και στις τρεις διατάξεις')}</span></div><form id="create-form" novalidate><div class="layout"><div class="stack"><section class="card"><div class="card-head"><h2>1 · ${tx('Shipment & Shipper','Αποστολή & αποστολέας')}</h2></div><div class="card-body form-grid"><label class="field"><span>${tx('Shipment','Αποστολή')} *</span><select name="shipment" id="shipment"><option value="">${tx('Select a Shipment','Επιλέξτε αποστολή')}</option><option value="SHP-DEMO-104" ${form.shipment?'selected':''}>SHP-DEMO-104 · DEMO-AWB-104</option></select><small>${tx('Fictional existing Shipment. Fixed after creation.','Υπάρχουσα δοκιμαστική αποστολή. Δεν αλλάζει μετά τη δημιουργία.')}</small></label>${companySelect(form.shipper)}</div></section><section class="card"><div class="card-head"><h2>2 · ${tx('Goods covered by this declaration','Κόλι που καλύπτει η διασάφηση')} ${mark(1)}</h2><span class="tag">${form.selected.length} / ${eligible().length} ${tx('eligible','επιλέξιμα')}</span></div>${form.shipment?goodsTable(form.selected,true):`<div class="empty"><p>${tx('Choose a Shipment to see its goods.','Επιλέξτε αποστολή για να δείτε τα κόλι της.')}</p></div>`}<div class="card-foot">${tx('Whole-Order selection selects its collis. Empty coverage is allowed only before submission.','Η επιλογή παραγγελίας επιλέγει τα κόλι της. Κενή κάλυψη επιτρέπεται μόνο πριν την υποβολή.')}</div></section><section class="card"><div class="card-head"><h2>3 · ${tx('Starting point','Αφετηρία διαδικασίας')}</h2></div><div class="card-body"><label class="check-label"><input type="checkbox" name="advanced" id="advanced" ${form.advanced?'checked':''}><strong>${tx('Record a procedure already underway','Καταχώριση διαδικασίας που έχει ήδη ξεκινήσει')}</strong></label><p class="small muted spaced">${tx('Normally start at Awaiting submission. Use this only when actual confirmations are already known.','Συνήθως ξεκινά στην Αναμονή υποβολής. Χρησιμοποιήστε το μόνο όταν είναι γνωστές οι πραγματικές επιβεβαιώσεις.')}</p>${form.advanced?`<div class="spaced">${advancedFields()}</div>`:''}</div></section></div><aside class="stack"><section class="card"><div class="card-head"><h2>${tx('Creation review','Έλεγχος δημιουργίας')}</h2></div><div class="card-body stack"><dl class="facts single"><div><dt>${tx('Shipment','Αποστολή')}</dt><dd class="mono">${form.shipment||'—'}</dd></div><div><dt>${tx('Shipper','Αποστολέας')}</dt><dd>${esc(form.shipper)||tx('Not selected yet','Δεν επιλέχθηκε ακόμη')}</dd></div><div><dt>${tx('Covered collis','Καλυπτόμενα κόλι')}</dt><dd>${form.selected.length}</dd></div><div><dt>${tx('Initial status','Αρχική κατάσταση')}</dt><dd>${stageText(form.advanced?form.stage:'draft')}</dd></div></dl><div class="notice">${tx('Saving this sample changes this browser preview only.','Η αποθήκευση αλλάζει μόνο αυτή την προεπισκόπηση.')}</div><div id="create-error" class="notice error hidden" role="alert"></div><button class="btn primary full" type="submit">${tx('Create sample Import','Δημιουργία δοκιμαστικής εισαγωγής')}</button></div></section><div class="notice warning">${mark(6)} ${tx('Whole-colli coverage is provisional. A partial shipment example does not establish whether sub-colli clearance is required.','Η κάλυψη ολόκληρων κόλι είναι προσωρινή παραδοχή. Το παράδειγμα δεν επιβεβαιώνει αν απαιτείται εκτελωνισμός μέρους ενός κόλι.')}</div></aside></div></form>`;}
function reference(){return `<div class="page-top"><div><div class="breadcrumbs">${tx('Existing Shipment screen · fixture reconstruction','Υπάρχουσα οθόνη αποστολής · δοκιμαστική αναπαράσταση')}</div><h1>SHP-DEMO-104</h1><p class="subtitle">${tx('Current screen sections and portal styling as a comparison reference. Not an existing Imports page.','Οι σημερινές ενότητες και το ύφος της πύλης ως αναφορά σύγκρισης. Δεν είναι υπάρχουσα οθόνη εισαγωγών.')}</p></div><div class="row">${btn(tx('Compare directions','Σύγκριση προτάσεων'),'compare')}${btn(tx('Back to Import','Επιστροφή στην εισαγωγή'),'details')}</div></div><div class="layout"><div class="stack"><section class="card"><div class="card-head"><h2>${tx('Transport and timing','Μεταφορά και χρόνοι')}</h2><span class="badge success">${tx('Arrived','Αφίχθηκε')}</span></div><div class="card-body"><dl class="facts"><div><dt>${tx('Mode','Τρόπος')}</dt><dd>${tx('Air','Αεροπορική')}</dd></div><div><dt>${tx('Document','Έγγραφο')}</dt><dd class="mono">DEMO-AWB-104</dd></div><div><dt>${tx('Origin','Αφετηρία')}</dt><dd>Demo Origin Warehouse</dd></div><div><dt>${tx('Destination','Προορισμός')}</dt><dd>Demo Receiving Warehouse</dd></div></dl></div></section>${shipmentContext(true,true)}</div><aside class="stack"><section class="card"><div class="card-head"><h2>${tx('Purchase orders','Παραγγελίες')}</h2></div><div class="card-body"><p class="mono">DEMO-201</p><p class="small muted">2 ${tx('collis','κόλι')}</p><hr style="border:0;border-top:1px solid var(--border);margin:16px 0"><p class="mono">DEMO-202</p><p class="small muted">1 ${tx('colli','κόλι')}</p></div></section><section class="card"><div class="card-head"><h2>${tx('Attachments','Συνημμένα')}</h2></div><div class="card-body muted">${tx('No sample files','Χωρίς δοκιμαστικά αρχεία')}</div></section><div class="notice">${tx('Read-only reference. Import fields and customs actions belong to the proposed directions, not this existing screen.','Αναφορά μόνο για ανάγνωση. Τα στοιχεία και οι ενέργειες εισαγωγής ανήκουν στις προτεινόμενες διατάξεις.')}</div></aside></div>`;}
function stateContent(){if(ui.state==='loading')return `<section class="card"><div class="card-body" role="status"><p class="muted">${tx('Loading sample record…','Φόρτωση δοκιμαστικής εγγραφής…')}</p><div class="skeleton short spaced"></div><div class="skeleton big"></div><div class="skeleton"></div>${btn(tx('Finish simulated loading','Ολοκλήρωση δοκιμαστικής φόρτωσης'),'retry')}</div></section>`;return `<section class="card empty"><div class="symbol">${ui.state==='error'?'!':'○'}</div><h1>${ui.state==='error'?tx('Could not load the Import','Δεν ήταν δυνατή η φόρτωση'):tx('No sample results','Δεν υπάρχουν δοκιμαστικά αποτελέσματα')}</h1><p>${ui.state==='error'?tx('Simulated read failure. This is not “no Import”. Your sample edits remain available when you retry.','Προσομοίωση αποτυχίας ανάγνωσης, όχι απουσία εγγραφής. Οι αλλαγές διατηρούνται για επανάληψη.'):tx('An empty result does not create a record or select goods automatically.','Το κενό αποτέλεσμα δεν δημιουργεί εγγραφή και δεν επιλέγει αυτόματα κόλι.')}</p>${btn(tx('Return to sample data','Επιστροφή στα δοκιμαστικά δεδομένα'),'retry','primary')}</section>`;}
function notes(){const list=[['Coverage belongs to the declaration','Η κάλυψη ανήκει στη διασάφηση','All eligible collis are initially selected. Another non-cancelled Import on the same Shipment excludes its collis. Order groups are a selection convenience.','Όλα τα επιλέξιμα κόλι προεπιλέγονται. Άλλη μη ακυρωμένη εισαγωγή στην ίδια αποστολή αποκλείει τα κόλι της. Οι ομάδες παραγγελιών διευκολύνουν την επιλογή.'],['Ownership and locks','Κυριότητα και κλειδώματα','Shipment is fixed at creation. Shipper and coverage lock at submission; MRN/date lock at positive result. Shipper is selected from existing Companies.','Η αποστολή είναι σταθερή από τη δημιουργία. Αποστολέας και κάλυψη κλειδώνουν στην υποβολή· MRN/ημερομηνία στο θετικό αποτέλεσμα.'],['One recorded next step','Ένα καταγεγραμμένο επόμενο βήμα','Inspection is not rejection. Explicit no-payment confirmation bypasses payment. Completion means receipt of the Άδεια, not its issuance or payment alone.','Ο έλεγχος δεν είναι απόρριψη. Η ρητή επιβεβαίωση μη απαίτησης πληρωμής παρακάμπτει την πληρωμή. Ολοκλήρωση σημαίνει παραλαβή Άδειας.'],['Related data stays read-only','Τα σχετικά στοιχεία μένουν μόνο για ανάγνωση','The Shipment context panel is a new composition of existing cards/facts. All displayed values are fictional whole-Shipment examples. Employees will decide the final field set and totals.','Το πλαίσιο αποστολής είναι νέα σύνθεση υπαρχουσών καρτών. Τα στοιχεία είναι δοκιμαστικά για όλη την αποστολή. Τα τελικά πεδία/σύνολα θα συζητηθούν με το τμήμα.'],['No physical side effects','Χωρίς φυσικές μεταβολές','Customs confirmation does not split Orders, move goods, change regimes or alter packing. All prototype actions are temporary and resettable.','Η τελωνειακή επιβεβαίωση δεν χωρίζει παραγγελίες, δεν μετακινεί κόλι και δεν αλλάζει καθεστώτα ή συσκευασία. Οι δοκιμαστικές ενέργειες είναι προσωρινές.'],['Whole-colli assumption remains open','Η παραδοχή ολόκληρου κόλι παραμένει ανοιχτή','Ask the department whether part of one colli can be cleared. FRO-359 remains pending this answer. The three layouts do not settle that business question.','Το τμήμα πρέπει να επιβεβαιώσει αν εκτελωνίζεται μέρος ενός κόλι. Το FRO-359 αναμένει αυτή την απάντηση. Οι διατάξεις δεν επιλύουν το επιχειρησιακό ερώτημα.']];return `<section class="notes" id="rule-notes"><div class="row between"><h2>${tx('Review notes · FRO-359 rules','Σημειώσεις · κανόνες FRO-359')}</h2>${fresh()}</div><p class="small muted">${tx('New compositions: Import workbench, customs action panel, related-context panel and this reviewer toolbar/notes layer. Existing controls and tokens are mirrored from the portal.','Νέες συνθέσεις: χώρος εισαγωγής, τελωνειακές ενέργειες, σχετικά στοιχεία και εργαλεία ανασκόπησης. Τα στοιχεία ελέγχου και το ύφος προέρχονται από την πύλη.')}</p><div class="notes-list">${list.map((n,i)=>`<article class="note" id="note-${i+1}"><span class="number">${i+1}</span><div><h3>${tx(n[0],n[1])}</h3><p>${tx(n[2],n[3])}</p></div></article>`).join('')}</div></section>`;}
function render(){let focusId=document.activeElement?.id;document.documentElement.lang=ui.lang;document.querySelector('#app').innerHTML=reviewer()+shell()+`<main id="main">${ui.state!=='default'?stateContent():ui.layout==='compare'?compare():ui.layout==='reference'?reference():ui.view==='create'?creation():details()}${ui.notes?notes():''}<footer class="footer-note">FRO-360 · ${tx('Local concept round 1 · Fictional records · Switching pages/scenarios resets the sample context · Layouts are proposals, FRO-359 defines the rules.','Τοπική προεπισκόπηση 1 · Δοκιμαστικές εγγραφές · Η αλλαγή σελίδας/σεναρίου επαναφέρει τα δεδομένα · Οι διατάξεις είναι προτάσεις, το FRO-359 ορίζει τους κανόνες.')}</footer></main>`;syncUrl();if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
function openModal(kind){modalKind=kind;lastFocus=document.activeElement;const m=document.querySelector('#modal');let title='',body='',confirm=tx('Confirm','Επιβεβαίωση');const date=()=>field('eventDate',tx('Actual event date','Πραγματική ημερομηνία γεγονότος'),TODAY,'date','',true);
 if(kind==='edit'){editDraft={selected:[...record.selected],shipper:record.shipper,mrn:record.mrn,mrnDate:record.mrnDate};title=tx('Edit Import','Επεξεργασία εισαγωγής');body=record.stage==='draft'?companySelect(editDraft.shipper)+`<div><h3>${tx('Covered goods','Καλυπτόμενα κόλι')}</h3>${goodsTable(editDraft.selected,true)}</div>`:`<div class="form-grid">${field('edit-mrn','MRN',record.mrn,'text','',true)}${field('edit-mrnDate',tx('MRN date','Ημερομηνία MRN'),record.mrnDate,'date','',true)}</div><div class="notice">${tx('Shipment, Shipper and covered goods are locked.','Αποστολή, αποστολέας και καλυπτόμενα κόλι είναι κλειδωμένα.')}</div>`;confirm=tx('Save sample changes','Αποθήκευση δοκιμαστικών αλλαγών');}
 else if(kind==='submit'){title=tx('Confirm declaration submission','Επιβεβαίωση υποβολής διασάφησης');body=`<div class="notice">${tx('This records a submission that already happened. It does not submit anything to customs. Shipper and covered goods will lock.','Καταγράφει υποβολή που έχει ήδη γίνει. Δεν υποβάλλει στο τελωνείο. Αποστολέας και καλυπτόμενα κόλι θα κλειδώσουν.')}</div><div class="form-grid">${field('eventMrn','MRN',MRN,'text','',true)}${field('eventMrnDate',tx('MRN date','Ημερομηνία MRN'),TODAY,'date','',true)}${date()}</div>`;}
 else if(kind==='positive'){title=tx('Confirm positive customs result','Επιβεβαίωση θετικού αποτελέσματος');body=date()+`<label class="field"><span>${tx('Payment requirement','Απαίτηση πληρωμής')} *</span><select id="eventPayment" name="eventPayment" required><option value="">${tx('Choose explicitly','Επιλέξτε ρητά')}</option><option value="yes">${tx('Payment required','Απαιτείται πληρωμή')}</option><option value="no">${tx('No payment required','Δεν απαιτείται πληρωμή')}</option></select></label><div class="notice">${tx('MRN/date and file removal lock after this confirmation. No payment required goes directly to awaiting Άδεια.','Με την επιβεβαίωση κλειδώνουν MRN/ημερομηνία και αφαίρεση αρχείων. Χωρίς απαίτηση πληρωμής ακολουθεί αναμονή Άδειας.')}</div>`;}
 else if(kind==='cancel-record'){title=tx('Cancel pre-submission record','Ακύρωση εγγραφής πριν την υποβολή');body=`<div class="notice warning">${tx('Manager simulation. History/files stay readable; its saved coverage becomes available. This does not withdraw a submitted declaration.','Προσομοίωση διαχειριστή. Ιστορικό/αρχεία διατηρούνται και η κάλυψη αποδεσμεύεται. Δεν ανακαλείται υποβληθείσα διασάφηση.')}</div><label class="field"><span>${tx('Reason','Αιτιολογία')} *</span><textarea name="reason" id="reason" required></textarea></label>`;confirm=tx('Cancel sample record','Ακύρωση δοκιμαστικής εγγραφής');}
 else if(kind==='context'){title=tx('Shipment context · sample','Στοιχεία αποστολής · δοκιμή');body=shipmentContext(true);}
 else {const map={documentary:['Record documentary inspection referral','Καταχώριση παραπομπής για έλεγχο εγγράφων'],physical:['Record physical inspection referral','Καταχώριση παραπομπής για φυσικό έλεγχο'],inspection:['Inspection completed · result pending','Ο έλεγχος ολοκληρώθηκε · αναμονή αποτελέσματος'],payment:['Confirm payment','Επιβεβαίωση πληρωμής'],receipt:['Confirm Άδεια receipt','Επιβεβαίωση παραλαβής Άδειας']};title=tx(...map[kind]);body=date()+`<div class="notice">${kind==='receipt'?tx('Confirm actual receipt of Άδεια Τελωνισθέντων Εμπορευμάτων. This completes the Import. An attachment is optional.','Επιβεβαιώστε την παραλαβή της Άδειας Τελωνισθέντων Εμπορευμάτων. Ολοκληρώνει την εισαγωγή. Η επισύναψη είναι προαιρετική.'):kind==='payment'?tx('Confirm a payment that actually occurred. Completion still requires Άδεια receipt.','Επιβεβαιώστε πληρωμή που πραγματοποιήθηκε. Η ολοκλήρωση απαιτεί παραλαβή Άδειας.'):tx('Inspection is not rejection. This action does not imply a positive result.','Ο έλεγχος δεν είναι απόρριψη. Η ενέργεια δεν συνεπάγεται θετικό αποτέλεσμα.')}</div>`;}
 m.innerHTML=`<form id="modal-form" novalidate><div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="btn sm quiet" data-action="close" aria-label="${tx('Close','Κλείσιμο')}">×</button></div><div class="modal-body">${body}<div id="modal-error" class="modal-error notice error" role="alert"></div>${kind!=='context'?`<label class="check-label modal-review"><input type="checkbox" name="fail" id="simulate-failure">${tx('Review tool: simulate a failed save','Εργαλείο ανασκόπησης: αποτυχία αποθήκευσης')}</label>`:''}</div><div class="modal-foot">${btn(tx('Close without changes','Κλείσιμο χωρίς αλλαγές'),'close')}${kind==='context'?'':`<button class="btn ${kind==='cancel-record'?'danger':'primary'}" type="submit">${confirm}</button>`}</div></form>`;document.body.style.overflow='hidden';m.showModal();m.querySelector('input:not([type=checkbox]),select,textarea')?.focus();}
function modalError(message){document.querySelector('#modal-error').textContent=message;}
function validDate(d){return /^\d{4}-\d{2}-\d{2}$/.test(d)&&d<=TODAY;}
function validMRN(s){return /^[A-Z0-9]{18}$/.test(s.trim().toUpperCase());}
function confirmModal(formEl){let data=new FormData(formEl),kind=modalKind,date=data.get('eventDate');if(data.get('fail')){modalError(tx('Simulated failure. Nothing changed; your entered values are retained.','Προσομοίωση αποτυχίας. Καμία αλλαγή· οι τιμές διατηρούνται.'));return;}
 if(kind==='edit'){if(record.stage==='draft'){record.shipper=data.get('shipper')||'';record.selected=[...editDraft.selected];}else{let mrn=data.get('edit-mrn').trim().toUpperCase(),dt=data.get('edit-mrnDate');if(!validMRN(mrn)||!validDate(dt)||dt>record.events.find(e=>e.kind==='submission').date){modalError(tx('Enter an 18-character alphanumeric MRN and a date no later than submission.','Εισαγάγετε MRN 18 αλφαριθμητικών χαρακτήρων και ημερομηνία όχι μετά την υποβολή.'));return;}record.mrn=mrn;record.mrnDate=dt;}record.events.push(ev('edited'));}
 else if(kind==='cancel-record'){if(!String(data.get('reason')||'').trim()){modalError(tx('A cancellation reason is required.','Απαιτείται αιτιολογία ακύρωσης.'));return;}record.cancelled=true;record.reason=data.get('reason');record.events.push(ev('cancel'));}
 else {let last=record.events.filter(e=>!['created','edited'].includes(e.kind)).at(-1);if(!validDate(date)||(last&&date<last.date)){modalError(tx('Use a date on or after the previous event and no later than 3 Nov 2026 (fixture today).','Η ημερομηνία πρέπει να είναι μετά ή ίδια με το προηγούμενο γεγονός και έως 3 Νοεμβρίου 2026 (δοκιμαστικό σήμερα).'));return;}
 if(kind==='submit'){let mrn=String(data.get('eventMrn')||'').trim().toUpperCase(),dt=data.get('eventMrnDate');if(!record.shipper||!record.selected.length){modalError(tx('Choose a Shipper and at least one eligible colli in Edit before confirming submission.','Επιλέξτε αποστολέα και τουλάχιστον ένα επιλέξιμο κόλι από την Επεξεργασία.'));return;}if(!validMRN(mrn)||!validDate(dt)||dt>date){modalError(tx('MRN must have 18 letters/digits; MRN date must not be after submission.','Το MRN απαιτεί 18 γράμματα/ψηφία· η ημερομηνία του δεν μπορεί να είναι μετά την υποβολή.'));return;}record.mrn=mrn;record.mrnDate=dt;record.stage='result';record.events.push(ev('submission',date));}
 else if(kind==='positive'){if(!['yes','no'].includes(data.get('eventPayment'))){modalError(tx('Explicitly choose whether payment is required.','Επιλέξτε ρητά αν απαιτείται πληρωμή.'));return;}record.payment=data.get('eventPayment')==='yes';record.stage=record.payment?'payment':'permit';record.events.push(ev('positive',date,{payment:record.payment}));}
 else {record.stage=({documentary:'documentary',physical:'physical',inspection:'result',payment:'permit',receipt:'complete'})[kind];record.events.push(ev(kind,date));}}
 document.querySelector('#modal').close();render();announce(tx('Sample record updated. No real data was saved.','Η δοκιμαστική εγγραφή ενημερώθηκε. Δεν αποθηκεύτηκαν πραγματικά δεδομένα.'));
}
function createImport(){let fail=msg=>{let e=document.querySelector('#create-error');e.textContent=msg;e.classList.remove('hidden');e.scrollIntoView({block:'nearest'});};if(!form.shipment)return fail(tx('Select a Shipment first.','Επιλέξτε πρώτα αποστολή.'));let stage=form.advanced?form.stage:'draft',events=[ev('created')];if(form.advanced){if(!form.shipper||!form.selected.length)return fail(tx('A submitted procedure requires a Shipper and covered goods.','Η υποβληθείσα διαδικασία απαιτεί αποστολέα και καλυπτόμενα κόλι.'));if(!validMRN(form.mrn))return fail(tx('MRN must contain exactly 18 letters/digits.','Το MRN πρέπει να περιέχει ακριβώς 18 γράμματα/ψηφία.'));let dates=[form.mrnDate,form.submissionDate];events.push(ev('submission',form.submissionDate));if(['documentary','physical'].includes(stage)){dates.push(form.inspectionDate);events.push(ev(stage,form.inspectionDate));}if(['payment','permit','complete'].includes(stage)){dates.push(form.positiveDate);events.push(ev('positive',form.positiveDate,{payment:form.payment==='yes'}));if(stage!=='payment'&&form.payment==='yes'){dates.push(form.paymentDate);events.push(ev('payment',form.paymentDate));}if(stage==='complete'){dates.push(form.receiptDate);events.push(ev('receipt',form.receiptDate));}}if(dates.some(d=>!validDate(d))||dates.some((d,i)=>i&&d<dates[i-1]))return fail(tx('Confirm every required date in chronological order, no later than fixture today (3 Nov 2026).','Επιβεβαιώστε όλες τις ημερομηνίες με χρονική σειρά, έως το δοκιμαστικό σήμερα (3 Νοεμβρίου 2026).'));}
 record={id:'IMP-DEMO-022',shipment:form.shipment,shipper:form.shipper,selected:[...form.selected],stage,payment:['payment','permit','complete'].includes(stage)?form.payment==='yes':null,mrn:form.advanced?form.mrn.trim().toUpperCase():'',mrnDate:form.advanced?form.mrnDate:'',events,files:[],cancelled:false};ui.view='details';ui.tab='goods';if(!['a','b','c'].includes(ui.layout))ui.layout='a';render();window.scrollTo(0,0);announce(tx('Sample Import created in this preview only.','Η δοκιμαστική εισαγωγή δημιουργήθηκε μόνο στην προεπισκόπηση.'));
}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;
 if(a==='lang'){ui.lang=b.dataset.lang;render();}else if(a==='direction'){ui.layout=b.dataset.layout;ui.view='details';render();window.scrollTo(0,0);}else if(a==='compare'){ui.layout='compare';render();window.scrollTo(0,0);}else if(a==='reference'){ui.layout='reference';render();window.scrollTo(0,0);}else if(a==='details'){ui.view='details';if(!['a','b','c'].includes(ui.layout))ui.layout='a';render();window.scrollTo(0,0);}else if(a==='create'){resetFixture();ui.view='create';if(!['a','b','c'].includes(ui.layout))ui.layout='a';render();window.scrollTo(0,0);}else if(a==='reset'){resetFixture();ui.state='default';render();announce(tx('Sample reset.','Επαναφορά δοκιμαστικών δεδομένων.'));}else if(a==='notes'){ui.notes=!ui.notes;render();if(ui.notes)document.querySelector('#rule-notes').scrollIntoView({block:'start'});}else if(a==='note'){ui.notes=true;render();document.querySelector('#note-'+b.dataset.n)?.scrollIntoView({block:'center'});}else if(a==='tab'){ui.tab=b.dataset.tab;render();}else if(a==='retry'){ui.state='default';render();}else if(a==='nav-info'){announce(tx('Reference navigation only. This preview explores Imports.','Η πλοήγηση είναι ενδεικτική. Η προεπισκόπηση αφορά εισαγωγές.'));}else if(a==='close'){document.querySelector('#modal').close();}else if(a==='file-add'){if(!canEdit())return;record.files.push({id:Date.now(),name:'Demo customs document.pdf'});render();announce(tx('Sample file added; customs status is unchanged.','Προστέθηκε δοκιμαστικό αρχείο· η κατάσταση δεν άλλαξε.'));}else if(a==='file-remove'){if(!canEdit()||afterPositive(record))return;record.files=record.files.filter(f=>String(f.id)!==b.dataset.id);render();}else if(a==='fixture-dates'){form.mrn=MRN;['mrnDate','submissionDate','inspectionDate','positiveDate','paymentDate','receiptDate'].forEach(k=>form[k]=TODAY);render();}else if(['edit','submit','positive','documentary','physical','inspection','payment','receipt','cancel-record','context'].includes(a)){openModal(a);}
});
document.addEventListener('input',e=>{if(e.target.closest('#create-form')&&e.target.name&&!['checkbox','select-one'].includes(e.target.type))form[e.target.name]=e.target.value;});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.control){ui[el.dataset.control]=el.value;if(el.dataset.control==='scenario')resetFixture();render();return;}if(el.dataset.colli||el.dataset.group){let inModal=!!el.closest('dialog'),target=inModal?editDraft:form,ids=el.dataset.colli?[el.dataset.colli]:goods.filter(g=>g.order===el.dataset.group&&!blocked().includes(g.id)).map(g=>g.id);target.selected=el.checked?[...new Set([...target.selected,...ids])]:target.selected.filter(id=>!ids.includes(id));if(inModal){const section=el.closest('.table-wrap');section.outerHTML=goodsTable(target.selected,true);}else render();return;}if(el.closest('#create-form')&&el.name){form[el.name]=el.type==='checkbox'?el.checked:el.value;if(el.name==='shipment')form.selected=form.shipment?eligible().map(g=>g.id):[];if(el.name==='stage'&&form.stage==='payment')form.payment='yes';render();}});
document.addEventListener('submit',e=>{if(e.target.id==='create-form'){e.preventDefault();createImport();}if(e.target.id==='modal-form'){e.preventDefault();confirmModal(e.target);}});
document.querySelector('#modal').addEventListener('close',()=>{document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();});
render();
